def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent cooperation and defection
    op_c = 0
    my_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            op_c += 1
        if history[i][0] == 'C':
            my_c += 1
    op_d = n - op_c
    my_d = n - my_c

    # Last opponent move and recent behavior
    opp_last = history[-1][1]
    my_last = history[-1][0]

    # Consecutive opponent defections at end
    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    # Consecutive opponent cooperations at end
    opp_coop_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_coop_streak += 1
        else:
            break

    # Detection of always-defect
    if op_c == 0:
        return 'D'

    # Detection of always-cooperate: exploit but keep some cooperation
    if op_d == 0:
        # Last few rounds: defect to maximize payoff
        if n >= 95:
            return 'D'
        # Otherwise cooperate, but occasionally defect
        if n > 10 and n % 11 == 0:
            return 'D'
        return 'C'

    # Near the end, exploit cooperative opponents
    if n >= 95:
        if op_c > op_d:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # If opponent has been mostly cooperative, cooperate
    if op_c * 3 >= n * 2:
        # Opponent is generally cooperative
        if opp_last == 'D':
            # Punish single defection, but forgive quickly
            if opp_def_streak >= 2:
                return 'D'
            # Single defection: retaliate once
            return 'D'
        # Opponent cooperated: cooperate
        # Occasionally defect to probe
        if n > 20 and n % 17 == 0:
            return 'D'
        return 'C'

    # If opponent has been mostly defective, defect
    if op_d * 3 >= n * 2:
        return 'D'

    # Mixed opponent: use tit-for-tat with forgiveness
    if opp_last == 'D':
        # Opponent just defected
        if opp_def_streak >= 3:
            # Long defection streak: defect
            return 'D'
        if opp_def_streak == 2:
            # Two consecutive: defect to punish
            return 'D'
        # Single defection: retaliate once, then forgive
        if my_last == 'D':
            return 'C'
        return 'D'
    else:
        # Opponent just cooperated
        if my_last == 'D' and opp_def_streak == 0:
            # We defected, they cooperated: return to cooperation
            return 'C'
        # Cooperate
        return 'C'

    return 'C'
